通过一个阶乘函数的不同写法将 Go 程序员进行划分。初级 Go 程序员

package facfunc Factorial(n int) int &#123;	res := 1	for i := 1; i &lt;= n; i++ &#123;		res *= i	&#125;	return res&#125;

函数式 Go 程序员package facfunc Factorial(n int) int &#123;	if n == 0 &#123;		return 1	&#125; else &#123;		return Factorial(n - 1) * n	&#125;&#125;

泛型 Go 程序员package facfunc Factorial(n interface&#123;&#125;) interface&#123;&#125; &#123;	v, valid := n.(int)	if !valid &#123;		return 0	&#125;	res := 1	for i := 1; i &lt;= v; i++ &#123;		res *= i	&#125;	return res&#125;

多线程优化的 Go 程序员package facimport &quot;sync&quot;func Factorial(n int) int &#123;	var (		left, right = 1, 1		wg sync.WaitGroup	)	wg.Add(2)	pivot := n / 2	go func() &#123;		for i := 1; i &lt; pivot; i++ &#123;			left *= i		&#125;		wg.Done()	&#125;()	go func() &#123;		for i := pivot; i &lt;= n; i++ &#123;			right *= i		&#125;		wg.Done()	&#125;()	wg.Wait()	return left * right&#125;

发现型 Go 模式package facfunc Factorial(n int) &lt;-chan int &#123;	ch := make(chan int)	go func() &#123;		prev := 1		for i := 1; i &lt;= n; i++ &#123;			v := prev * i			ch &lt;- v			prev = v		&#125;		close(ch)	&#125;()	return ch&#125;

使用成熟的解决方案修复 Go 缺陷package fac/** * @see https://en.wikipedia.org/wiki/Factorial */type IFactorial interface &#123;	CalculateFactorial() int&#125;// FactorialImpl implements IFactorial.var _ IFactorial = (*FactorialImpl)(nil)/** * Used to find factorial of the n. */type FactorialImpl struct &#123;	/**	 * The n.	 */	n int&#125;/** * Constructor of the FactorialImpl. * * @param n the n. */func NewFactorial(n int) *FactorialImpl &#123;	return &amp;FactorialImpl&#123;		n: n,	&#125;&#125;/** * Gets the n to use in factorial function. * * @return int. */func (this *FactorialImpl) GetN() int &#123;	return this.n&#125;/** * Sets the n to use in factorial function. * * @param n the n. * @return void. */func (this *FactorialImpl) SetN(n int) &#123;	this.n = n&#125;/** * Returns factorial of the n. * * @todo remove &quot;if&quot; statement. Maybe we should use a factory or somthing? * * @return int. */func (this *FactorialImpl) CalculateFactorial() int &#123;	if this.n == 0 &#123;		return 1	&#125;	n := this.n	this.n = this.n - 1	return this.CalculateFactorial() * n&#125;

高级 Go 程序员package fac// Factorial returns n!.func Factorial(n int) int &#123;	res := 1	for i := 1; i &lt;= n; i++ &#123;		res *= i	&#125;	return res&#125;

Rob Pikepackage fac// Factorial returns n!.func Factorial(n int) int &#123;	res := 1	for i := 1; i &lt;= n; i++ &#123;		res *= i	&#125;	return res&#125;

